.cm{box-sizing:border-box;width:100%;height:100%;display:flex;flex-direction:column;gap:8px;padding:12px 14px;background:var(--window);color:var(--text);font:13px/1.4 "Segoe UI",system-ui,sans-serif;overflow:hidden}
.cm *{box-sizing:border-box}
.top{display:flex;justify-content:space-between;align-items:flex-start}
.label{color:var(--muted);font-size:12.5px;font-weight:500}
.valuerow{display:flex;align-items:baseline;gap:6px}
.value{font-size:28px;font-weight:700;letter-spacing:-.02em;line-height:1.2}
.unit{color:var(--muted);font-size:12.5px}
.change{font-size:12px;font-weight:600;padding:1px 7px;border-radius:10px}
.change.up{color:var(--positive);background:color-mix(in srgb,var(--positive) 14%,transparent)}
.change.down{color:var(--negative);background:color-mix(in srgb,var(--negative) 14%,transparent)}
.ranges{display:flex;gap:2px;background:var(--background);border-radius:8px;padding:2px}
.range{padding:3px 9px;border-radius:6px;font-size:12px;font-weight:500;color:var(--muted);cursor:pointer}
.range:hover{color:var(--text)}
.range.selected{background:var(--window);color:var(--accent);box-shadow:0 1px 2px rgba(20,20,50,.1)}
.chart{flex:1;min-height:70px;position:relative}
.chart svg{display:block;width:100%;height:100%}
.band{fill:color-mix(in srgb,var(--accent) 10%,transparent)}
.avg{stroke:var(--muted);stroke-width:1;stroke-dasharray:3 3;opacity:.6}
.line{fill:none;stroke:var(--accent);stroke-width:2;stroke-linejoin:round;stroke-linecap:round}
.area{fill:url(#cmgrad)}
.dot{fill:var(--window);stroke:var(--accent);stroke-width:2}
.legend{display:flex;gap:12px;color:var(--muted);font-size:11.5px}
.legend b{color:var(--text);font-weight:600}
.breakdown{display:flex;flex-direction:column;gap:3px;border-top:1px solid var(--border);padding-top:8px}
.item{display:grid;grid-template-columns:78px 1fr 58px;align-items:center;gap:8px;font-size:12px;padding:1px 4px;border-radius:5px;cursor:pointer}
.item:hover{background:var(--hover)}
.item .name{color:var(--muted)}
.track{position:relative;height:8px}
.track:before{content:"";position:absolute;left:50%;top:-2px;bottom:-2px;width:1px;background:var(--border)}
.bar{position:absolute;top:0;height:8px;border-radius:3px}
.bar.rev{background:var(--positive)}
.bar.cost{background:var(--negative)}
.item .amt{text-align:right;font-weight:600;font-variant-numeric:tabular-nums}
.item .amt.cost{color:var(--negative)}
.empty{color:var(--muted);font-size:12px;padding:20px 0;text-align:center}

