function render(root, props, fire) {
  const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const money = v => (v < 0 ? '−$' : '$') + Math.abs(v).toFixed(2);
  const host = root.querySelector('.cm');
  if (props.positiveColor) host.style.setProperty('--positive', props.positiveColor); else host.style.removeProperty('--positive');
  if (props.negativeColor) host.style.setProperty('--negative', props.negativeColor); else host.style.removeProperty('--negative');

  // headline
  root.querySelector('.label').textContent = props.title || 'Crush margin';
  root.querySelector('.value').textContent = money(props.margin || 0);
  root.querySelector('.unit').textContent = props.unit || '/gal';
  const ch = root.querySelector('.change'), c = props.change || 0;
  ch.className = 'change ' + (c >= 0 ? 'up' : 'down');
  ch.textContent = (c >= 0 ? '▲ ' : '▼ ') + Math.abs(c).toFixed(2);

  // range selector
  const RANGES = ['7D', '30D', '90D'];
  const rg = root.querySelector('.ranges');
  rg.innerHTML = RANGES.map(r => '<span class="range' + (r === props.range ? ' selected' : '') + '" data-r="' + r + '">' + r + '</span>').join('');
  rg.querySelectorAll('.range').forEach(el => el.onclick = () => fire('rangeChanged', { range: el.dataset.r }));

  // trend chart with high-low band and average
  const chart = root.querySelector('.chart');
  const n = { '7D': 7, '30D': 30, '90D': 90 }[props.range] || 30;
  const pts = (props.history || []).map(h => +h.value).filter(v => !isNaN(v)).slice(-n);
  const legend = root.querySelector('.legend');
  if (pts.length < 2) {
    chart.innerHTML = '<div class="empty">No history</div>'; legend.innerHTML = '';
  } else {
    const W = 400, H = 100, pad = 6;
    const lo = Math.min.apply(null, pts), hi = Math.max.apply(null, pts);
    const avg = pts.reduce((a, b) => a + b, 0) / pts.length;
    const min = lo - (hi - lo) * .15, max = hi + (hi - lo) * .15 || hi + 1;
    const x = i => pad + i * (W - 2 * pad) / (pts.length - 1);
    const y = v => H - pad - (v - min) * (H - 2 * pad) / (max - min);
    const d = pts.map((v, i) => (i ? 'L' : 'M') + x(i).toFixed(1) + ' ' + y(v).toFixed(1)).join(' ');
    const last = pts.length - 1;
    chart.innerHTML = '<svg viewBox="0 0 ' + W + ' ' + H + '" preserveAspectRatio="none">' +
      '<defs><linearGradient id="cmgrad" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="var(--accent)" stop-opacity=".22"/><stop offset="1" stop-color="var(--accent)" stop-opacity="0"/></linearGradient></defs>' +
      '<rect class="band" x="0" y="' + y(hi) + '" width="' + W + '" height="' + (y(lo) - y(hi)) + '"/>' +
      '<line class="avg" x1="0" x2="' + W + '" y1="' + y(avg) + '" y2="' + y(avg) + '"/>' +
      '<path class="area" d="' + d + ' L' + x(last) + ' ' + H + ' L' + x(0) + ' ' + H + 'Z"/>' +
      '<path class="line" d="' + d + '" vector-effect="non-scaling-stroke"/>' +
      '<circle class="dot" cx="' + x(last) + '" cy="' + y(pts[last]) + '" r="3.5" vector-effect="non-scaling-stroke"/></svg>';
    legend.innerHTML = '<span>High <b>' + money(hi) + '</b></span><span>Low <b>' + money(lo) + '</b></span><span>Avg <b>' + money(avg) + '</b></span>';
  }

  // breakdown: revenues to the right, costs to the left of the centre line
  const bd = root.querySelector('.breakdown');
  const items = props.breakdown || [];
  bd.style.display = props.showBreakdown === false || !items.length ? 'none' : '';
  const peak = Math.max.apply(null, items.map(i => Math.abs(+i.value || 0)).concat([0.01]));
  bd.innerHTML = items.map(i => {
    const v = +i.value || 0, w = Math.abs(v) / peak * 50, cost = v < 0;
    return '<div class="item" data-name="' + esc(i.name) + '"><span class="name">' + esc(i.name) + '</span>' +
      '<span class="track"><span class="bar ' + (cost ? 'cost' : 'rev') + '" style="' + (cost ? 'right:50%' : 'left:50%') + ';width:' + w + '%"></span></span>' +
      '<span class="amt' + (cost ? ' cost' : '') + '">' + money(v) + '</span></div>';
  }).join('');
  bd.querySelectorAll('.item').forEach(el => el.onclick = () => fire('componentClicked', { name: el.dataset.name }));
}
